#!/usr/bin/env node
// i18n-lab/build-names.mjs — extract the official English names that the generated data already
// carries (`appellation`) into en/names.js. Run after `npm run build-data`.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(path.dirname(fileURLToPath(import.meta.url)), 'en', 'names.js');

const names = new Map();
let conflicts = 0;

const add = (zh, en, where) => {
  if (!zh || !en) return;
  const clean = String(zh).trim();
  const value = String(en).trim();
  if (!clean || !value || clean === value) return;
  const prev = names.get(clean);
  if (prev && prev !== value) {
    console.warn(`  conflict: ${clean} = "${prev}" vs "${value}" (${where}) — keeping first`);
    conflicts++;
    return;
  }
  names.set(clean, value);
};

for (const [file, pick] of [
  ['data/chess.json', (r) => [r.name, r.appellation, 'chess']],
  ['data/tokens.json', (r) => [r.name, r.appellation, 'tokens']],
]) {
  const abs = path.join(ROOT, file);
  if (!fs.existsSync(abs)) { console.warn(`  skip ${file} (run npm run build-data first)`); continue; }
  const data = JSON.parse(fs.readFileSync(abs, 'utf8'));
  for (const rec of Object.values(data)) {
    const [zh, en, where] = pick(rec);
    add(zh, en, where);
  }
}

const sorted = [...names.entries()].sort((a, b) => b[0].length - a[0].length);
const body = sorted.map(([zh, en]) => `  ${JSON.stringify(zh)}: ${JSON.stringify(en)},`).join('\n');
fs.writeFileSync(OUT, `// Generated by i18n-lab/build-names.mjs — do not edit by hand.
// Source: the official \`appellation\` field already present in data/chess.json / data/tokens.json.
export const NAMES = {
${body}
};
`);
console.log(`wrote ${OUT}: ${sorted.length} official EN names, ${conflicts} conflicts`);
